using ghidra.framework.plugintool;

public class ToolStateFactory {
	static ToolStateFactory() {
	    PluggableServiceRegistry.registerPluggableService(typeof(ToolStateFactory), new ToolStateFactory());
	}
	
	public static ToolState createToolState(PluginTool tool, DomainObject domainObject) {
		ToolStateFactory toolStateFactory = PluggableServiceRegistry.getPluggableService(typeof(ToolStateFactory));
